assert.equal(winArgs[0], "powershell");
assert.ok(winArgs.includes("-Silent"), "silent 时追加 -Silent");
assert.ok(winArgs.some((a) => a === "-Title=标题"), "单 token -Title= 传参");
assert.ok(winArgs.some((a) => a === "-Message=内容 -x"), "含空格/前导 '-' 的消息单 token 不被拆");
const macArgs = buildSystemCommand("darwin", "标题", '说"话', { silent: false, toastScript: "t.ps1" });
assert.equal(macArgs[0], "osascript");
assert.match(macArgs.join(" "), /display notification/);
assert.ok(macArgs.join(" ").includes('sound name "Glass"'), "非静默带 Glass 提示音");
assert.ok(!macArgs.join(" ").includes('说话"'), "消息内引号被转义");
assert.equal(buildSystemCommand("linux", "t", "m", { silent: true, notifySendAvailable: false, toastScript: "t.ps1" }), null, "notify-send 不可用返回 null");
assert.deepEqual(buildSystemCommand("linux", "t", "m", { silent: true, toastScript: "t.ps1" }), ["notify-send", "t", "m"]);

// sessionTitleOf：从 session.events 的 session/title 事件取标题
const titledAgent = {
  id: "session-1",
  session: { events: [{ type: "other", data: {} }, { type: "session/title", data: { title: "优化 notifier 插件" } }] },
};
assert.equal(sessionTitleOf(titledAgent), "优化 notifier 插件", "取最后一个标题事件");
assert.equal(sessionTitleOf({ id: "session-1", session: { events: [] } }), undefined, "无标题事件返回 undefined");
assert.equal(sessionTitleOf({ id: "session-1" }), undefined, "无 session 返回 undefined");
assert.equal(sessionTitleOf(undefined), undefined, "无 agent 返回 undefined");
assert.equal(sessionTitleOf({ id: "session-1", session: { events: "bad" } }), undefined, "events 非数组容错");
assert.equal(
  sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: "优".repeat(80) } }] } }),
  "优".repeat(40),
  "标题截断 40 字符"
);

// sessionTitleOf 接入脱敏链（issue #30）：标题源自会话内容，进入通知与历史前
// 敏感片段必须打码；正常标题不含敏感特征、脱敏后原样透传保持可读
assert.ok(
  !sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: `修复 ${"a".repeat(48)} 泄漏` } }] } })!.includes("aaaa"),
  "标题中长 hex 密钥片段被打码为 <token>"
);
assert.equal(
  sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: `修复 ${"f".repeat(30)} 泄漏` } }] } }),
  "修复 <token> 泄漏",
  "≥24 位 hex 长串在标题中打码"
);
assert.ok(
  !sessionTitleOf({ session: { events: [{ type: "session/title", data: { title: "联系 admin@corp.example.com 处理部署" } }] } })!.includes("admin@"),
  "标题中邮箱地址被打码为 <email>"
);
assert.equal(
  sessionTitleOf(titledAgent),
  "优化 notifier 插件",
  "正常标题脱敏后原样透传（可读性不受影响）"
);

// loopback 围栏：回环放行、非回环拒绝
assert.equal(isLoopbackRequest(fakeReq()), true);
assert.equal(isLoopbackRequest(fakeReq({ socket: { remoteAddress: "10.0.0.2" } })), false);

packages/dsh-notifier/test/unit-sanitize.source:
// @ts-nocheck
/**
 * dsh-notifier — unit：错误文本脱敏（sanitizeErrorText）。
 *
 * 覆盖：路径/令牌/密钥打码 + 截断；issue #6 扩展（GitHub PAT / PEM 私钥 /
 * 连接串凭据 / 邮箱）；规则顺序硬约束回归；FP 证伪回归（已删规则的误伤
 * 形态必须保持原样）；性能护栏（防灾难性回溯）；PEM 限窗/赋值分隔符/amqps
 * 评审修复回归。
 */
import { assert } from "./helpers.ts";
import { sanitizeErrorText } from "../lib/index.js";

// 路径/令牌/密钥打码 + 截断
assert.equal(sanitizeErrorText("failed /home/me/dev/x.yaml: EACCES"), "failed <path>: EACCES", "用户路径打码");
assert.equal(sanitizeErrorText("token: 3f9a2b7c4d5e6f708192a3b4c5d6e7f8091a2b3c4d"), "token: <token>", "长 hex 令牌打码");
assert.ok(!sanitizeErrorText("password=s3cr3t").includes("s3cr3t"), "密钥赋值掩蔽");
assert.equal(sanitizeErrorText("错".repeat(500)).length, 300, "截断 300");
assert.equal(sanitizeErrorText("普通错误"), "普通错误", "普通文本原样");
assert.equal(sanitizeErrorText("x".repeat(40)), "<token>", "长重复字符按令牌打码");

// 推送前修复（P1）：脱敏漏网补充——JWT / AKIA 前缀 / /root 路径
assert.equal(
  sanitizeErrorText("Authorization: Bearer eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c"),
  "Authorization=<redacted> <token>",
  "Authorization 头掩蔽 + JWT（含 - _ 的 base64url）整段打码"
);
assert.equal(sanitizeErrorText("aws key AKIAIOSFODNN7EXAMPLE used"), "aws key <token> used", "AKIA 前缀密钥打码");
assert.ok(!sanitizeErrorText("Cannot read /root/.ssh/id_rsa: denied").includes("/root"), "/root 路径打码");
assert.ok(!sanitizeErrorText("open /etc/passwd denied").includes("/etc"), "/etc 路径打码");
// 防误伤：普通含下划线/连字符的英文单词不应被 JWT/AKIA 规则误打码
assert.equal(sanitizeErrorText("the-key_is-here and also_fine"), "the-key_is-here and also_fine", "普通文本不被 JWT 规则误伤");

// ---- issue #6 脱敏扩展：GitHub PAT / PEM 私钥 / 连接串凭据 / 邮箱 ----
// GitHub PAT classic（ghp/gho/ghu/ghs/ghr + 恰 36 位字母数字）
const patCore36 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
assert.equal(sanitizeErrorText(`token ghp_${patCore36} end`), "token <token> end", "GitHub PAT classic 打码");
for (const prefix of ["gho", "ghu", "ghs", "ghr"]) {
  assert.equal(sanitizeErrorText(`${prefix}_${patCore36}`), "<token>", `GitHub PAT ${prefix}_ 前缀打码`);
}
// 长度边界锁定：35/37 位不命中（业界共识写死长度），且不被通用长串规则部分命中
assert.equal(sanitizeErrorText(`ghp_${patCore36.slice(0, 35)}`), `ghp_${patCore36.slice(0, 35)}`, "PAT 35 位不误伤");
assert.equal(sanitizeErrorText(`ghp_${patCore36}X`), `ghp_${patCore36}X`, "PAT 37 位不误伤");
// fine-grained PAT（区间长度）
const fgPat = `github_pat_${"A".repeat(22)}_${"B".repeat(59)}`;
assert.equal(sanitizeErrorText(`bad ${fgPat}!`), "bad <token>!", "GitHub fine-grained PAT 打码");
// 回归：通用长串规则不得对 github_pat_ 部分命中产生残缺掩码
assert.ok(!sanitizeErrorText(fgPat).includes("_"), "fine-grained PAT 无残缺残留");

// PEM 私钥：完整块（含 \r\n 变体）与孤立 BEGIN 兜底；证书/PUBLIC KEY 不误伤
const pemBody = "MIIEowIBAAKCAQEA0Z3VS5JJcds3xfn/yGWyifZ6IWVpYFKEzBNGIFfD8hV0v";
assert.equal(
  sanitizeErrorText(`-----BEGIN RSA PRIVATE KEY-----\n${pemBody}\n-----END RSA PRIVATE KEY-----\nok`),
  "<private-key>\nok",
  "PEM 完整私钥块打码"
);
assert.ok(
  !sanitizeErrorText(`-----BEGIN EC PRIVATE KEY-----\r\n${pemBody}\r\n-----END EC PRIVATE KEY-----`).includes("MIIEow"),
  "PEM 私钥块（\\r\\n）打码"
);
assert.ok(
  !sanitizeErrorText(`-----BEGIN OPENSSH PRIVATE KEY-----\nb3BlbnNzaC1rZXktdjEAAAAA\n尾随`).includes("b3BlbnNzaC"),
  "PEM 孤立 BEGIN（无 END，错误消息截断常态）兜底打码"
);
assert.equal(
  sanitizeErrorText("-----BEGIN CERTIFICATE-----\nc2hvcnRib2R5\n-----END CERTIFICATE-----"),
  "-----BEGIN CERTIFICATE-----\nc2hvcnRib2R5\n-----END CERTIFICATE-----",
  "证书块不误伤"
);
assert.ok(!sanitizeErrorText("-----BEGIN PUBLIC KEY-----\nc2hvcnRib2R5\n-----END PUBLIC KEY-----").includes("<private-key>"), "PUBLIC KEY 不误伤");

// 数据库/消息队列连接串凭据：scheme 保留、凭据整体掩蔽
assert.equal(
  sanitizeErrorText("postgres://admin:s3cret@db.local:5432/app down"),
  "postgres://<redacted>@db.local:5432/app down",
  "postgres 连接串掩蔽且 scheme 正确（防 $1 组号回归）"
);
assert.equal(sanitizeErrorText("redis://:MyPass@127.0.0.1:6379"), "redis://<redacted>@127.0.0.1:6379", "redis 空用户名形态掩蔽");
assert.equal(
  sanitizeErrorText("mongodb+srv://dev:pw123@cluster0.abc12.mongodb.net/test"),
  "mongodb+srv://<redacted>@cluster0.abc12.mongodb.net/test",
  "mongodb+srv 连接串掩蔽"
);
assert.equal(sanitizeErrorText("POSTGRES://U:P@H"), "POSTGRES://<redacted>@H", "大写 scheme 掩蔽（i flag）");
assert.equal(
  sanitizeErrorText("jdbc:mysql://host/db?user=root&password=topsecret"),
  "jdbc:mysql://host/db?user=root&password=<redacted>",
  "JDBC 凭据在 query 参数，由密钥赋值规则覆盖"
);
assert.equal(sanitizeErrorText("postgres://u:p@ss@h"), "postgres://<redacted>@ss@h", "畸形双 @ 锁定残缺行为（URL 规范要求编码）");

// 邮箱（严格版）：正常邮箱打码；资源引用/版本号不误伤
assert.equal(sanitizeErrorText("mail a.b-c@example.co.uk end"), "mail <email> end", "邮箱打码");
assert.equal(sanitizeErrorText("loaded image@2x.png"), "loaded image@2x.png", "资源引用 @2x 不误伤");
assert.equal(sanitizeErrorText("need @scope/pkg@1.2.3"), "need @scope/pkg@1.2.3", "包版本 pkg@1.2.3 不误伤");
// 顺序回归：DSN 掩蔽后占位符不得被邮箱规则二次命中产生 <<email>>
assert.equal(
  sanitizeErrorText("mysql://admin:s3cret@db.example.com down"),
  "mysql://<redacted>@db.example.com down",
  "DSN 与邮箱规则顺序回归"
);
// 尖括号引用形态（issue #30）：双断言放行 <user@host>，不再整体漏网
assert.equal(
  sanitizeErrorText("From: John <john.doe@corp.example.com> signed"),
  "From: John <<email>> signed",
  "尖括号包裹的真实邮箱正常打码"
);
// 占位符不被二次破坏（issue #30）：裸 <redacted>@真实域名 形态必须原样保留
assert.equal(
  sanitizeErrorText("<redacted>@db.example.com down"),
  "<redacted>@db.example.com down",
  "DSN 掩码占位符不被邮箱规则二次命中"
);

// 规则顺序硬约束回归
assert.equal(
  sanitizeErrorText("postgres://u:eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c@h"),
  "postgres://<redacted>@h",
  "DSN 先于 JWT：连接串内嵌 JWT 整体掩蔽，用户名不残留"
);
assert.equal(
  sanitizeErrorText("postgres://u:token@hostname down"),
  "postgres://<redacted>@hostname down",
  "DSN 先于密钥赋值：host 保留、凭据不劣化残留"
);

// 边界与容错：Symbol 入参不抛错；截断窗口腰斩行为锁定
assert.doesNotThrow(() => sanitizeErrorText(Symbol("x")), "Symbol 入参不抛 TypeError");
assert.equal(sanitizeErrorText(Symbol("x")), "Symbol(x)", "Symbol 入参转字符串");
assert.equal(sanitizeErrorText("前".repeat(296) + `ghp_${patCore36}`), "前".repeat(296) + "<tok", "占位符落在截断窗口被腰斩（锁定行为）");

// FP 证伪回归：已删除规则的高频误伤形态必须保持原样（防止将来加回来）
assert.equal(sanitizeErrorText("Date.now()=1718000000000"), "Date.now()=1718000000000", "13 位毫秒时间戳原样（信用卡规则证伪）");
assert.equal(sanitizeErrorText("Chrome/120.0.0.0 Safari/537.36"), "Chrome/120.0.0.0 Safari/537.36", "UA 版本号原样（IPv4 规则证伪）");
assert.equal(sanitizeErrorText("order 1234567890123456 paid"), "order 1234567890123456 paid", "16 位订单号原样");

// 性能护栏：大文本全链无灾难性回溯（宽松上限防 CI 抖动，非基准测试）
{
  const big = "postgres://admin:s3cret@db.example.com error jwt eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.SflKxwRJSMeKKF2QT4fwpM\n".repeat(10000);
  const t0 = Date.now();
  sanitizeErrorText(big);
  const cost = Date.now() - t0;
  assert.ok(cost < 1000, `约 1MB 文本脱敏耗时 ${cost}ms < 1000ms（防回溯退化）`);
}

// 性能护栏（对抗形态）：多 BEGIN 无 END 输入曾因完整块规则 O(k·n) 阻塞宿主数秒
// （评审实测 1MB 高密度 BEGIN 6-17s），限窗 {0,4096} 后必须保持线性量级
{
  const adversarial = "-----BEGIN PRIVATE KEY-----".repeat(20000); // 约 560KB
  const t0 = Date.now();
  const out = sanitizeErrorText(adversarial);
  const cost = Date.now() - t0;
  assert.ok(cost < 5000, `对抗输入（2 万 BEGIN 无 END）脱敏耗时 ${cost}ms < 5000ms（防 PEM 回溯回归）`);
  assert.ok(out.startsWith("<private-key>"), "对抗输入由孤立 BEGIN 兜底规则接住");
}

// ---- 评审修复回归：PEM 限窗 / 赋值分隔符收紧 / amqps ----

// PEM 完整块在窗口内仍整体打码；超窗伪块由孤立 BEGIN 兜底接住
{
  const pad = "A".repeat(5000);
  assert.equal(
    sanitizeErrorText(`-----BEGIN RSA PRIVATE KEY-----\n${pad}\n-----END RSA PRIVATE KEY-----\nok`),
    "<private-key>",
    "PEM 超 4096 窗口的真实长块：完整块失配后由兜底规则整体掩蔽到文本尾"
  );
  assert.equal(
    sanitizeErrorText("前 -----BEGIN PRIVATE KEY-----\nMIIEow\n-----END RSA PRIVATE KEY----- 后续可读"),
    "前 <private-key> 后续可读",
    "PEM 窗口内完整块打码且块后内容保留可读"
  );
}

// 密钥赋值规则：分隔符 [=:] 必须显式——自然语言不得误伤（评审 P1 回归）
assert.equal(sanitizeErrorText("auth failed: token expired"), "auth failed: token expired", "自然语言 token expired 不误伤");
assert.equal(sanitizeErrorText("request rejected: invalid token provided"), "request rejected: invalid token provided", "invalid token provided 不误伤");
assert.equal(sanitizeErrorText("password policy requires changes"), "password policy requires changes", "password policy 不误伤");
assert.equal(sanitizeErrorText("Authorization header missing"), "Authorization header missing", "Authorization header 不误伤");
// 显式赋值形态仍打码（含「键名: 空格 值」与引号形态）
assert.equal(sanitizeErrorText("token: abc123"), "token=<redacted>", "显式冒号赋值仍打码");
assert.equal(sanitizeErrorText('password = "s3cr3t"'), 'password=<redacted>"', "等号带空格+引号赋值仍打码（收尾引号残留为已知形态）");
assert.ok(!sanitizeErrorText("api_key=sk-live-9f8e7d6c5b4a").includes("sk-live"), "api_key= 赋值仍打码");

// amqps 连接串凭据：scheme 保留、凭据整体掩蔽（评审 P2 回归，不再半脱敏）
assert.equal(sanitizeErrorText("amqps://guest:guest@rabbit.local/vhost"), "amqps://<redacted>@rabbit.local/vhost", "amqps 连接串整体掩蔽");
assert.equal(sanitizeErrorText("AMQPS://u:p@h/v"), "AMQPS://<redacted>@h/v", "amqps 大写 scheme 掩蔽");

packages/dsh-notifier/test/e2e-approval..source:
// @ts-nocheck
/**
 * dsh-notifier — e2e：审批请求通知（approval/request waterfall）。
 *
 * 覆盖：五个事件监听器注册面；审批通知（工具中文名/任务标题/申请理由/
 * 行动建议，不短路、不暴露会话 id）；无标题降级；next 抛错原样传播；
 * notifyAsk=false 不通知；免打扰紧急例外 allowKinds（M4）。
 */
import { join } from "node:path";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { assert, makeNotifier, agentWithTitle } from "./helpers.ts";

/** 带 info 收集的 logger 覆盖。 */
function loggingOverride(infos) {
  return { logger: { warn: () => {}, info: (t) => infos.push(t) } };
}

const work = mkdtempSync(join(tmpdir(), "dnotify-e2e-approval-"));
try {
  // 监听器注册面 + 审批通知主流程
  {
    const infos = [];
    const { listeners } = await makeNotifier(work, {}, loggingOverride(infos));

    const approval = listeners.get("approval/request")[0];
    const status = listeners.get("agent/status")[0];
    const error = listeners.get("agent/error")[0];
    const turnStop = listeners.get("agent/turn-stopping")[0];
    const disposed = listeners.get("agent/disposed")[0];
    assert.ok(approval && status && error && turnStop && disposed, "五个事件监听器已注册");
    assert.equal(listeners.has("tools/pre-execute"), false, "不再挂 pre-execute（真实审批走 approval/request）");

    // approval/request：通知（工具中文名/任务标题/申请理由），不短路返回 next 结果
    const req = { toolName: "pwsh", agent: agentWithTitle("session-1", "优化 notifier 插件"), reason: "escalate sandbox to workspace-write: 需要写文件", signal: { aborted: false } };
    const outcome = await approval(req, async () => "allowed-once");
    assert.equal(outcome, "allowed-once", "不短路，返回 next 结果");
    assert.equal(infos.length, 1);
    assert.match(infos[0], /ask/);
    assert.match(infos[0], /任务「优化 notifier 插件」等待审批（工具「PowerShell 命令」）/, "审批通知带任务标题与工具中文名");
    assert.match(infos[0], /理由：escalate sandbox to workspace-write: 需要写文件/);
    assert.match(infos[0], /确认或拒绝/, "审批通知带行动建议");
    assert.ok(!infos[0].includes("session-"), "审批通知不暴露内部会话 id");

    // 无会话标题：降级为仅工具名
    const outcome2 = await approval({ toolName: "bash", agent: agentWithTitle("session-9", null) }, async () => "allowed-once");
    assert.equal(outcome2, "allowed-once");
    assert.match(infos[1], /工具「终端命令」等待审批/, "无标题时仅显示工具中文名");
    assert.ok(!infos[1].includes("任务「"), "无标题时不显示任务行");
    assert.ok(!infos[1].includes("session-9"), "无标题路径也不暴露会话 id");

    // next 抛错 → 原样传播（waterfall 兜底由上层负责），通知已先行发出
    await assert.rejects(approval(req, async () => {
      throw new Error("boom");
    }), /boom/);
    assert.equal(infos.length, 3, "next 抛错前通知已发出");
  }

  // notifyAsk=false（configFile）时 approval/request 不通知、不短路
  {
    const askOffCfg = join(work, "ask-off.json");
    writeFileSync(askOffCfg, JSON.stringify({ notifyAsk: false }));
    const infos = [];
    const { listeners } = await makeNotifier(work, { configFile: askOffCfg }, loggingOverride(infos));
    const approval = listeners.get("approval/request")[0];
    const outcome = await approval({ toolName: "bash", agent: { id: "session-1" } }, async () => "allowed-once");
    assert.equal(outcome, "allowed-once", "不短路");
    assert.equal(infos.length, 0, "notifyAsk=false 不通知");
  }

  // M4 免打扰紧急例外：allowKinds 中的 kind 在免打扰时段仍通知
  {
    // 窗口围绕当前时间动态构造（±2 分钟）：#181 —— 写死 "00:00"/"23:59" 假设
    // 全天覆盖，但实现是半开区间 [start, end)，23:59 这一分钟不命中，UTC 边缘必炸；
    // now 邻近 00:00 时 start > end，天然走实现的跨午夜分支（quiet-hours.ts）。
    const hhmm = (offsetMinutes) => {
      const t = new Date(Date.now() + offsetMinutes * 60_000);
      return `${String(t.getHours()).padStart(2, "0")}:${String(t.getMinutes()).padStart(2, "0")}`;
    };
    const qhOn = { enabled: true, start: hhmm(-2), end: hhmm(2) };
    const cfgAsk = join(work, "qh-ask.json");
    writeFileSync(cfgAsk, JSON.stringify({ quietHours: { ...qhOn, allowKinds: ["ask"] } }));
    const infos = [];
    const { listeners } = await makeNotifier(work, { configFile: cfgAsk, historyFile: join(work, "history-qh1.jsonl") }, loggingOverride(infos));
    const approval = listeners.get("approval/request")[0];
    await approval({ toolName: "pwsh", agent: agentWithTitle("qh-1", "免打扰审批", { turnEnd: 1 }) }, async () => "ok");
    assert.equal(infos.length, 1, "免打扰期间 ask 仍通知（紧急例外 allowKinds）");
    assert.match(infos[0], /ask/);

    // allowKinds 为空/不含 ask：免打扰生效则静默
    const cfgNone = join(work, "qh-none.json");
    writeFileSync(cfgNone, JSON.stringify({ quietHours: { ...qhOn, allowKinds: [] } }));
    const infos2 = [];
    const { listeners: listeners2 } = await makeNotifier(work, { configFile: cfgNone, historyFile: join(work, "history-qh2.jsonl") }, loggingOverride(infos2));
    await listeners2.get("approval/request")[0]({ toolName: "pwsh", agent: { id: "qh-2" } }, async () => "ok");
    assert.equal(infos2.filter((t) => !t.includes("被免打扰拦截")).length, 0, "无 allowKinds 时免打扰不产生实际通知");
    assert.ok(infos2.some((t) => t.includes("被免打扰拦截")), "被拦截仍记录日志（可核对发没发）");
  }
} finally {
  rmSync(work, { recursive: true, force: true });
}

packages/dsh-notifier/test/e2e-done.test.source:
// @ts-nocheck
/**
 * dsh-notifier — e2e：任务完成状态机 / 错误通知与合并 / 子代理分流。
 *
 * 覆盖：agent/status per-agent 状态机（多会话互不误报、连续 idle 不重复、
 * disposed 清理）；完成风暴聚合（首条即时 + 窗口补发聚合条）；agent/error
 * 通知与滚动窗口合并（含窗口过期计数、0=关闭）；子代理完成场景（issue #49：
 * fork 型委派按运行时归属拆分——归属成立默认静默/开关联动 subagent-done、
 * 归属不成立保护用户 fork 主线走 done；spawn 型 origin 用例与 S2 开关组合）。
 */
import { join } from "node:path";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { assert, makeNotifier, agentWithTitle, fakeAgents, waitMergeWindow, fakeReq, makeRes } from "./helpers.ts";
import { ROUTES } from "../lib/index.js";

/** 带 info 收集的 logger 覆盖。 */
function loggingOverride(infos) {
  return { logger: { warn: () => {}, info: (t) => infos.push(t) } };
}

const work = mkdtempSync(join(tmpdir(), "dnotify-e2e-done-"));
try {
  // per-agent 状态机 + 错误通知/合并 + 完成风暴聚合（同一实例）
  {
    const infos = [];
    const { listeners } = await makeNotifier(work, {}, loggingOverride(infos));
    const status = listeners.get("agent/status")[0];
    const disposed = listeners.get("agent/disposed")[0];
    const error = listeners.get("agent/error")[0];

    // agent/status：per-agent 状态机，多会话互不误报（真实宿主跑完一轮必有 turn/end，故 idle 断言带 turnEnd）
    status({ agent: agentWithTitle("session-1", "优化 notifier 插件"), status: "running" });
    status({ agent: agentWithTitle("session-2", "并行评审代码"), status: "running" });
    assert.equal(infos.length, 0, "running 不通知");
    status({ agent: agentWithTitle("session-2", "并行评审代码", { turnEnd: 1 }), status: "idle" });
    assert.equal(infos.length, 1, "session-2 完成通知一次");
    assert.match(infos[0], /done/);
    assert.match(infos[0], /任务「并行评审代码」已完成/, "完成通知带任务标题");
    assert.match(infos[0], /耗时：/, "完成通知带耗时");
    assert.ok(!infos[0].includes("session-"), "完成通知不暴露会话 id");
    // 完成风暴聚合窗口（3s）：等上一处完成的窗口结束，保证同 agent 下一轮是独立窗口
    await waitMergeWindow();
    status({ agent: agentWithTitle("session-1", "优化 notifier 插件", { turnEnd: 1 }), status: "idle" });
    assert.equal(infos.length, 2, "session-1 完成独立通知");
    assert.match(infos[1], /任务「优化 notifier 插件」已完成/);
    status({ agent: agentWithTitle("session-1", "优化 notifier 插件"), status: "idle" });
    assert.equal(infos.length, 2, "连续 idle 不重复通知");
    status({ agent: agentWithTitle("session-2", "并行评审代码"), status: "idle" });
    assert.equal(infos.length, 2, "session-2 无 running 记录不通知");

    // agent/disposed：清理状态机，防会话销毁后残留 idle 误报
    status({ agent: agentWithTitle("session-3", "临时会话"), status: "running" });
    disposed({ agent: agentWithTitle("session-3", "临时会话") });
    status({ agent: agentWithTitle("session-3", "临时会话"), status: "idle" });
    assert.equal(infos.length, 2, "disposed 清理后残留 idle 不误报");

    // agent/error：通知（任务标题/轮次步骤/错误信息）；60 秒窗口内同类错误合并
    error({ agent: agentWithTitle("session-1", "优化 notifier 插件"), turn: 1, step: 1, error: new Error("测试错误信息") });
    assert.equal(infos.length, 3);
    assert.match(infos[2], /error/);
    assert.match(infos[2], /任务「优化 notifier 插件」执行出错/, "错误通知带任务标题");
    assert.match(infos[2], /第 1 轮第 1 步：测试错误信息/, "轮次/步骤与错误信息同行");
    assert.ok(!infos[2].includes("session-"), "错误通知不暴露会话 id");
    error({ agent: agentWithTitle("session-1", "优化 notifier 插件"), turn: 1, step: 2, error: new Error("窗口内错误") });
    assert.equal(infos.length, 3, "窗口内同类错误合并，不重复通知");
    error({ agent: agentWithTitle("session-2", "并行评审代码"), turn: 1, step: 3, error: new Error("其他会话错误") });
    assert.equal(infos.length, 4, "不同会话独立合并窗口");
    assert.match(infos[3], /任务「并行评审代码」执行出错/);

    // 完成风暴聚合：窗口内第二条完成不即时，3s 后补发聚合条（防并行收尾刷屏）
    await waitMergeWindow(); // 窗口清零（error/turn 无完成窗口）
    status({ agent: agentWithTitle("storm-1", "并行任务A", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("storm-1", "并行任务A", { turnEnd: 1 }), status: "idle" });
    assert.equal(infos.length, 5, "聚合窗口首条即时通知");
    status({ agent: agentWithTitle("storm-2", "并行任务B", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("storm-2", "并行任务B", { turnEnd: 1 }), status: "idle" });
    assert.equal(infos.length, 5, "窗口内第二条挂起不即时发");
    await waitMergeWindow();
    assert.equal(infos.length, 6, "窗口到点补发聚合条");
    assert.match(infos[5], /另有 1 个任务已完成/, "聚合条文案带计数");
    assert.match(infos[5], /并行任务B/, "聚合条带最近标题");
  }

  // 错误合并窗口过期后通知并携带合并计数（独立实例：20ms 窗口）
  {
    const mergeCfg = join(work, "merge-observed.json");
    writeFileSync(mergeCfg, JSON.stringify({ errorMergeWindowMs: 20 }));
    const infos = [];
    const { listeners } = await makeNotifier(work, { configFile: mergeCfg }, loggingOverride(infos));
    const error = listeners.get("agent/error")[0];

    error({ agent: { id: "session-1" }, turn: 1, step: 1, error: new Error("e1") });
    assert.equal(infos.length, 1);
    error({ agent: { id: "session-1" }, turn: 1, step: 2, error: new Error("e2") });
    assert.equal(infos.length, 1, "窗口内合并");
    await new Promise((resolve) => setTimeout(resolve, 30));
    error({ agent: { id: "session-1" }, turn: 1, step: 3, error: new Error("e3") });
    assert.equal(infos.length, 2, "窗口过期后恢复通知");
    assert.match(infos[1], /另有 1 条同类错误/, "窗口过期后的通知携带合并计数");
    assert.match(infos[1], /窗口内其他错误/, "被合并错误保留摘要（e1）");
  }

  // 合并 0=关闭：错误不合并、完成不聚合（每条即时）
  {
    const cfg0 = join(work, "merge-off.json");
    writeFileSync(cfg0, JSON.stringify({ errorMergeWindowMs: 0, doneMergeWindowMs: 0 }));
    const infos = [];
    const { listeners } = await makeNotifier(work, { configFile: cfg0 }, loggingOverride(infos));
    const error = listeners.get("agent/error")[0];
    const status = listeners.get("agent/status")[0];

    // 错误：窗口=0 → 两条都通知（不合并）
    error({ agent: { id: "s0-1" }, turn: 1, step: 1, error: new Error("x1") });
    error({ agent: { id: "s0-1" }, turn: 1, step: 2, error: new Error("x2") });
    assert.equal(infos.length, 2, "errorMergeWindowMs=0：错误不合并");

    // 完成：窗口=0 → 连续两条完成都即时通知（不聚合）
    status({ agent: agentWithTitle("s0-a", "任务甲", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("s0-a", "任务甲", { turnEnd: 2 }), status: "idle" });
    status({ agent: agentWithTitle("s0-b", "任务乙", { turnEnd: 1 }), status: "running" });
    status({ agent: agentWithTitle("s0-b", "任务乙", { turnEnd: 2 }), status: "idle" });
    const doneCount = infos.filter((t) => /done/.test(t)).length;
    assert.equal(doneCount, 2, "doneMergeWindowMs=0：完成不聚合，两条都即时");
  }

  // 子代理完成：独立开关 notifySubagentDone（默认关）+ 独立事件类型 subagent-done
  {
    const subCfg = join(work, "subagent.json");

    // ── issue #49：fork 型委派子代理完成不再误报主任务 kind=done ──
    // fork 型委派（parentSession + seedLength、无 origin、depth=0）与用户 fork
    // 主线在持久化 header 上不可区分，判定补运行时归属（ctx.agents.get /
    // isOwnedBy）。原反例 1「仅 parentSession 无 origin 必须 walk done」与新
    // 验收冲突，已按归属成立/不成立拆分改写（旧语义不保留）：

    // A1：归属成立（父 live 且 isOwnedBy true）+ notifySubagentDone 默认关 →
    //     该轮完全静默，通知历史无新增任何记录（尤其无 done）。
    {
      const agents = fakeAgents(["main-parent", "fork-worker"], [["fork-worker", "main-parent"]]);
      const infos = [];
      const { listeners, routes } = await makeNotifier(
        work,
        { configFile: join(work, "sub-fork-owned.json"), historyFile: join(work, "history-a1.jsonl") },
        { agents, ...loggingOverride(infos) }
      );
      const status = listeners.get("agent/status")[0];
      const forkAgent = () => agentWithTitle("fork-worker", "fork 委派子任务", { parentSession: "main-parent", depth: 0, turnEnd: 1 });
      status({ agent: forkAgent(), status: "running" });
      status({ agent: forkAgent(), status: "idle" });
      assert.equal(infos.length, 0, "A1：fork 型委派归属成立且默认关时完全静默");
      // 通知历史复核（AC 验证入口）：静默路径不触发任何 appendHistory，读全量应为空
      const historyRoute = routes.find((r) => r.path === ROUTES.history);
      const { rec, res } = makeRes();
      await historyRoute.handler(fakeReq({}), res);
      const records = JSON.parse(rec.text).records || [];
      assert.equal(records.length, 0, "A1：通知历史无新增 done 记录");
    }

    // A2：同一场景开启 notifySubagentDone=true → 恰一条 subagent-done（文案含
    //     任务标题与耗时），且不得同时出现 kind=done。
    {
      const onCfg = join(work, "sub-fork-on.json");
      writeFileSync(onCfg, JSON.stringify({ notifySubagentDone: true }));
      const agents = fakeAgents(["main-parent2", "fork-worker2"], [["fork-worker2", "main-parent2"]]);
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: onCfg }, { agents, ...loggingOverride(infos) });
      const status = listeners.get("agent/status")[0];
      const forkAgent = () => agentWithTitle("fork-worker2", "fork 委派子任务B", { parentSession: "main-parent2", depth: 0, turnEnd: 1 });
      status({ agent: forkAgent(), status: "running" });
      status({ agent: forkAgent(), status: "idle" });
      assert.equal(infos.length, 1, "A2：开启开关时恰产生一条通知");
      assert.match(infos[0], /subagent-done/, "A2：事件类型为 subagent-done");
      assert.match(infos[0], /子任务「fork 委派子任务B」已完成/, "A2：文案带任务标题");
      assert.match(infos[0], /耗时：/, "A2：文案带耗时");
      assert.ok(!infos.some((t) => /dsh-notifier: done /.test(t)), "A2：不得同时出现 kind=done");
    }

    // B1 支 1：header 含 parentSession 但父 id 不在 live registry（父已销毁/
    // 冷 resume 脱离）→ 归属不成立，必须走主任务分支 kind=done（保护用户
    // fork 主线，#7 语义不回归），不得被静默或误报 subagent-done。
    {
      const agents = fakeAgents(["fork-orphan"], []);
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: join(work, "sub-fork-orphan.json") }, { agents, ...loggingOverride(infos) });
      const status = listeners.get("agent/status")[0];
      const mk = () => agentWithTitle("fork-orphan", "孤儿 fork 会话", { parentSession: "ghost-parent", turnEnd: 1 });
      status({ agent: mk(), status: "running" });
      status({ agent: mk(), status: "idle" });
      assert.equal(infos.length, 1, "B1：父 id 不存在时不被静默");
      assert.match(infos[0], /dsh-notifier: done /, "B1：发 kind=done 而非 subagent-done");
    }

    // B1 支 2：父 id live 但运行时不持有该 agent（isOwnedBy false，如无关
    // provider 复用 id）→ 归属不成立，同样走主任务分支 kind=done。
    {
      const agents = fakeAgents(["unrelated-parent", "fork-x"], []); // 无 (fork-x, unrelated-parent) 归属对
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: join(work, "sub-fork-unowned.json") }, { agents, ...loggingOverride(infos) });
      const status = listeners.get("agent/status")[0];
      const mk = () => agentWithTitle("fork-x", "无归属 fork 会话", { parentSession: "unrelated-parent", seedLength: 3, turnEnd: 1 });
      status({ agent: mk(), status: "running" });
      status({ agent: mk(), status: "idle" });
      assert.equal(infos.length, 1, "B1：isOwnedBy=false 时归属不成立，不被静默");
      assert.match(infos[0], /dsh-notifier: done /, "B1：发 kind=done 而非 subagent-done");
    }

    // D1：headless CLI 会话（header 仅 {cwd}，无 origin 无 parentSession）两信号
    //     皆否，保持现状按主任务分支处理（本 issue 不改变其分类）。
    {
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: join(work, "sub-headless.json") }, loggingOverride(infos));
      const status = listeners.get("agent/status")[0];
      const mk = () => agentWithTitle("headless-1", "headless CLI 会话", { cwd: "/tmp/dsh-cli", turnEnd: 1 });
      status({ agent: mk(), status: "running" });
      status({ agent: mk(), status: "idle" });
      assert.equal(infos.length, 1, "D1：headless 会话保持主任务分支现状");
      assert.match(infos[0], /dsh-notifier: done /);
    }

    // 反例 2（原 #7 回归防护保留）：主会话（无 header / 无 origin）必须走 done。
    {
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: join(work, "sub-main.json") }, loggingOverride(infos));
      const status = listeners.get("agent/status")[0];
      status({ agent: agentWithTitle("main-x", "主任务", { turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("main-x", "主任务", { turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 1, "主会话完成走 done");
      assert.match(infos[0], /dsh-notifier: done /);
    }

    // 默认关：子代理完成不通知，主任务完成不受影响
    {
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: join(work, "sub-default.json") }, loggingOverride(infos));
      const status = listeners.get("agent/status")[0];
      status({ agent: agentWithTitle("sub-1", "子任务A", { subagent: true, turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("sub-1", "子任务A", { subagent: true, turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 0, "notifySubagentDone 默认关：子代理完成不通知");
      status({ agent: agentWithTitle("main-1", "主任务", { turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("main-1", "主任务", { turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 1, "主任务完成不受子代理开关影响");
      assert.match(infos[0], /done/);
    }

    // 开启 notifySubagentDone：子代理完成用独立事件类型 subagent-done（标题/耗时）
    {
      const onCfg = join(work, "sub-on.json");
      writeFileSync(onCfg, JSON.stringify({ notifySubagentDone: true }));
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: onCfg }, loggingOverride(infos));
      const status = listeners.get("agent/status")[0];
      status({ agent: agentWithTitle("sub-2", "子任务B", { subagent: true, turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("sub-2", "子任务B", { subagent: true, turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 1);
      assert.match(infos[0], /subagent-done/, "子代理完成用独立事件类型");
      assert.match(infos[0], /子任务「子任务B」已完成/, "subagent-done 文案带任务标题");
      assert.match(infos[0], /耗时：/, "subagent-done 带耗时");
      assert.ok(!infos[0].includes("sub-2"), "子代理完成通知不暴露会话 id");
      // 等 subagent-done 的 3s 聚合窗口结束（否则主任务完成会被聚合挂起）
      await waitMergeWindow();
      status({ agent: agentWithTitle("main-2", "主任务2", { turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("main-2", "主任务2", { turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 2, "主任务仍走 done 类型");
      assert.match(infos[1], /done/);
    }

    // S2 回归：notifyTaskDone=false + notifySubagentDone=true 时子代理完成仍通知
    {
      const s2Cfg = join(work, "sub-s2.json");
      writeFileSync(s2Cfg, JSON.stringify({ notifyTaskDone: false, notifySubagentDone: true }));
      const infos = [];
      const { listeners } = await makeNotifier(work, { configFile: s2Cfg }, loggingOverride(infos));
      const status = listeners.get("agent/status")[0];
      status({ agent: agentWithTitle("sub-3", "子任务C", { subagent: true, turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("sub-3", "子任务C", { subagent: true, turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 1, "notifyTaskDone=false 不拦截子代理完成（S2）");
      assert.match(infos[0], /subagent-done/);
      status({ agent: agentWithTitle("main-3", "主任务3", { turnEnd: 1 }), status: "running" });
      status({ agent: agentWithTitle("main-3", "主任务3", { turnEnd: 1 }), status: "idle" });
      assert.equal(infos.length, 1, "notifyTaskDone=false 主任务不通知");
      // 既有 bug 修复回归：notifyTaskDone=false 时 idle 无条件重置状态，
      // 之后重开开关不会把旧的 running 误报为完成
      status({ agent: agentWithTitle("main-3", "主任务3", { turnEnd: 1 }), status: "running" });
      assert.equal(infos.length, 1, "running 仍不通知");
    }
  }
} finally {
  rmSync(work, { recursive: true, force: true });
}

packages/dsh-notifier/test/e2e-question-.source:
// @ts-nocheck
/**
 * dsh-notifier — e2e：用户提问通知（userQuestions 包装）与轮结束通知。
 *
 * 覆盖：internal/service 事件后包装 ask（this 绑定回归、返回值透传）、
 * 热重载解包重包不叠层、notifyQuestion=false 不通知；turn-stopping 默认关、
 * 开启后同一 (agent,turn) 去重、新轮次正常通知（serial 事件无 next 不抛错）。
 */
import { join } from "node:path";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { assert, makeNotifier } from "./helpers.ts";

const work = mkdtempSync(join(tmpdir(), "dnotify-e2e-question-"));
try {
  // 用户提问通知：包装 ctx.userQuestions.ask（internal/service 事件 + 热重载解包重包）
  {
    const infos = [];
    let fakeService = null;
    const { listeners } = await makeNotifier(work, { configFile: join(work, "question.json") }, {
      logger: { warn: () => {}, info: (t) => infos.push(t) },
      get: (name) => (name === "userQuestions" ? fakeService : undefined),
    });

    // 启动时 service 未注册 → 不包装；internal/service 事件到达后包装
    const serviceHandler = listeners.get("internal/service")[0];
    assert.ok(serviceHandler, "internal/service 监听器已注册");
    // 依赖 this 的类方法风格：验证包装后 this 仍绑定 service 实例（bind 回归测试）
    fakeService = {
      marker: "svc-marker",
      ask: async function (request) {
        return { answers: [this.marker] };
      },
    };
    serviceHandler("userQuestions", fakeService);

    const agent = { id: "session-1", session: { events: [{ type: "session/title", data: { title: "提问测试" } }] } };
    const result = await fakeService.ask({ agent, questions: [{ question: "今天吃了吗？" }] });
    assert.deepEqual(result, { answers: ["svc-marker"] }, "包装不改变原 ask 返回值，且 this 正确绑定");
    assert.ok(infos.some((t) => /question/.test(t)), "提问触发通知");
    assert.ok(infos.some((t) => /任务「提问测试」需要你回答/.test(t)), "提问通知带任务标题");
    assert.ok(infos.some((t) => /问题：今天吃了吗？/.test(t)), "提问通知带问题摘要");
    assert.ok(infos.some((t) => !t.includes("session-1")), "提问通知不暴露会话 id");

    // 热重载安全：重复触发 internal/service 时解包重包（不叠层、不重复通知）
    const askRef = fakeService.ask;
    serviceHandler("userQuestions", fakeService);
    assert.notEqual(fakeService.ask, askRef, "重复注册重新包装（解包旧包装）");
    const infoCountBefore = infos.length;
    const result2 = await fakeService.ask({ agent, questions: [{ question: "再问一次？" }] });
    assert.deepEqual(result2, { answers: ["svc-marker"] }, "解包重包后 ask 返回值不变，this 绑定正确");
    assert.equal(infos.length, infoCountBefore + 1, "解包重包不叠层，通知只发一次");

    // notifyQuestion=false 不通知（用独立的 service 实例，避免闭包捕获上一实例的配置）
    writeFileSync(join(work, "question-off.json"), JSON.stringify({ notifyQuestion: false }));
    let fakeService2 = null;
    const infos2 = [];
    const { listeners: listeners2 } = await makeNotifier(work, { configFile: join(work, "question-off.json"), historyFile: join(work, "history-q2.jsonl") }, {
      logger: { warn: () => {}, info: (t) => infos2.push(t) },
      get: (name) => (name === "userQuestions" ? fakeService2 : undefined),
    });
    const serviceHandler2 = listeners2.get("internal/service")[0];
    fakeService2 = { ask: async (request) => ({ answers: [] }) };
    serviceHandler2("userQuestions", fakeService2);
    await fakeService2.ask({ agent: { id: "session-2" }, questions: [{ question: "hi" }] });
    assert.equal(infos2.length, 0, "notifyQuestion=false 不通知");
  }

  // turn-stopping：默认不通知；serial 事件签名 cb(payload) 无 next——必须不抛错
  // （该断言依赖默认配置实例 + 开启 notifyTurnEnd 的对照实例）
  {
    const infos = [];
    const { listeners } = await makeNotifier(work, { configFile: join(work, "turn-default.json"), historyFile: join(work, "history-t1.jsonl") }, { logger: { warn: () => {}, info: (t) => infos.push(t) } });
    const turnStop = listeners.get("agent/turn-stopping")[0];
    assert.ok(turnStop, "turn-stopping 监听器已注册");
    let threw = false;
    try {
      await turnStop({ agent: { id: "session-1" }, turn: 4 });
    } catch (error) {
      threw = true;
    }
    assert.equal(threw, false, "serial 事件（无 next 参数）下监听器不抛错");
    assert.equal(infos.length, 0, "turn-stopping 默认不通知");

    // 开启 notifyTurnEnd 后 turn-stopping 通知(配置经 configFile 生效,apply 参数不接收通知开关)
    const turnEndCfg = join(work, "notify-turn-end.json");
    writeFileSync(turnEndCfg, JSON.stringify({ notifyTurnEnd: true }));
    const infosOn = [];
    const { listeners: listenersOn } = await makeNotifier(work, { configFile: turnEndCfg, historyFile: join(work, "history-t2.jsonl") }, { logger: { warn: () => {}, info: (t) => infosOn.push(t) } });
    const turnStopOn = listenersOn.get("agent/turn-stopping")[0];
    const agentWithEvents = { id: "session-1", session: { events: [{ type: "session/title", data: { title: "优化 notifier 插件" } }] } };
    await turnStopOn({ agent: agentWithEvents, turn: 4 });
    assert.ok(infosOn.some((t) => /turn-end/.test(t)), "notifyTurnEnd 开启后 turn-stopping 触发通知");
    assert.ok(infosOn.some((t) => /任务「优化 notifier 插件」第 4 轮工作已完成/.test(t)), "轮次完成通知带任务标题与轮次号");
    assert.ok(infosOn.some((t) => !t.includes("session-1")), "轮次完成通知不暴露会话 id");
    const countAfterFirst = infosOn.filter((t) => t.includes("turn-end")).length;
    // 同轮重复 emit（模拟事件被反复触发/热重载叠加）不重复通知——防「日志一堆」
    await turnStopOn({ agent: agentWithEvents, turn: 4 });
    await turnStopOn({ agent: agentWithEvents, turn: 4 });
    assert.equal(infosOn.filter((t) => t.includes("turn-end")).length, countAfterFirst, "同一 (agent,turn) 重复 turn-stopping 只通知一次");
    // 新的一轮（turn 5）仍正常通知
    await turnStopOn({ agent: agentWithEvents, turn: 5 });
    assert.equal(infosOn.filter((t) => t.includes("turn-end")).length, countAfterFirst + 1, "新轮次仍正常通知");
  }
} finally {
  rmSync(work, { recursive: true, force: true });
}
